// kernel_source.cpp: see kernel_source.h. The embedded table is generated by
// tools/embed_kernels.py into kernels_embedded.cpp at build time.
#include "kernel_source.h"
#include <fstream>
#include <sstream>
namespace igm {
extern const char *const kEmbeddedKernelNames[];
extern const char *const kEmbeddedKernelBodies[];
extern const int kEmbeddedKernelCount;
std::string kernel_source(const std::string &dir, const std::string &name) {
    std::ifstream f(dir + "/" + name, std::ios::binary);
    if (f) { std::stringstream ss; ss << f.rdbuf(); return ss.str(); }
    for (int i = 0; i < kEmbeddedKernelCount; i++) if (name == kEmbeddedKernelNames[i]) return kEmbeddedKernelBodies[i];
    return "";
}
}
